]$reference$::jsonb;
 item jsonb; course uuid;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(data) LOOP
  SELECT id INTO STRICT course FROM public.courses WHERE name=item->>'course';
  PERFORM public.publish_personal_tee(course,item->>'layout',item->>'tee',
    (item->>'rating')::numeric,(item->>'slope')::int,item->>'source',item->'holes');
 END LOOP;
END $pilot$;
